def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    last_me = me[-1]
    last_op = op[-1]

    op_d = 0
    op_d_5 = 0
    op_d_10 = 0
    op_d_20 = 0
    unprov = 0
    unprov_5 = 0
    unprov_10 = 0
    unprov_20 = 0
    punish_10 = 0
    punish_20 = 0
    cd_total = 0

    for i in range(n):
        if op[i] == 'D':
            op_d += 1
            if i >= n - 5:
                op_d_5 += 1
            if i >= n - 10:
                op_d_10 += 1
            if i >= n - 20:
                op_d_20 += 1

        prev_me = 'C' if i == 0 else me[i - 1]
        if op[i] == 'D' and prev_me == 'C':
            unprov += 1
            if i >= n - 5:
                unprov_5 += 1
            if i >= n - 10:
                unprov_10 += 1
            if i >= n - 20:
                unprov_20 += 1

        if i > 0 and me[i - 1] == 'D':
            if op[i] == 'D':
                if i >= n - 10:
                    punish_10 += 1
                if i >= n - 20:
                    punish_20 += 1
            else:
                cd_total += 1

    cd_streak = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'D' and op[i] == 'C':
            cd_streak += 1
        else:
            break

    if n >= 2 and op_d == n:
        return 'D'
    if op_d_10 >= 8 or unprov_10 >= 4:
        return 'D'
    if op_d_10 >= 5 and unprov_10 >= 2:
        return 'D'
    if op_d_20 >= 13 or unprov_20 >= 5:
        return 'D'
    if n >= 30 and unprov >= max(5, n // 15):
        return 'D'

    if last_op == 'D':
        provoked = n >= 2 and me[-2] == 'D'
        if provoked and unprov_20 <= 2 and op_d_20 <= 8:
            return 'C'
        return 'D'

    if last_me == 'D':
        if cd_streak >= 2 and unprov_20 == 0 and op_d_20 <= 2:
            return 'D'
        if cd_streak >= 1 and n >= 88 and unprov_20 <= 1 and op_d_20 <= 2:
            return 'D'
        if cd_total >= 4 and unprov <= 2 and op_d <= 2:
            return 'D'
        return 'C'

    if 90 <= n <= 94 and unprov == 0 and op_d <= 1 and cd_streak == 0:
        if rng.random() < 0.08:
            return 'D'

    if unprov_5 >= 3 or op_d_5 >= 4:
        return 'D'

    return 'C'
